//
//*************************************************************************************************
#define FSI_RX_TRIG_WIDTH_0_RX_TRIG_WIDTH_S   0U
#define FSI_RX_TRIG_WIDTH_0_RX_TRIG_WIDTH_M   0xFFFFU   // Output Pulse Width

//*************************************************************************************************
