#define FSI_RX_TRIG_CTRL_1_TRIG_SEL_M      0x1EU         // Input Select for Trigger
#define FSI_RX_TRIG_CTRL_1_RX_TRIG_DLY_S   8U
#define FSI_RX_TRIG_CTRL_1_RX_TRIG_DLY_M   0xFFFFFF00U   // Delay for Trigger generation

//*************************************************************************************************
//
